async function refreshExternal(showToast = true) {
  const day = getSelectedDay();
  if (day?.park) state.selectedPark = day.park === 'off-day' ? state.selectedPark : day.park;
  const park = state.selectedPark;
  const tasks = [fetchWeather(park)];
  if (PARKS[park]?.entityId) tasks.push(fetchLive(park));
  await Promise.all(tasks);
  renderAll();
  evaluateAlerts();
  if (showToast) toast(navigator.onLine ? 'Dados atualizados.' : 'Offline: mostrando últimos dados salvos.');
}

function evaluateAlerts() {
  const day = getSelectedDay();
  if (!day || day.date !== getOrlandoParts().date) return;
  const status = currentPlanStatus(day);
  if (status.delay > Number(state.settings.delayThreshold||15)) notifyOnce(`delay-${day.date}-${Math.floor(status.delay/10)}`, 'Roteiro atrasado', status.detail);
  const w = relevantWeather(state.weatherCache[day.park]);
  if (w.risk.score > 0) notifyOnce(`weather-${day.date}-${w.current?.time}`, 'Mudança no tempo', 'Há risco de chuva/trovoadas. Considere priorizar atrações cobertas ou sensíveis ao clima.');
  const live = state.liveCache[day.park];
  const next = day.activities.find(a=>!a.replanDeferred&&!isDone(a.id)&&!isSkipped(a.id));
  if (next && live) {
    const match = findLiveMatch(next,live.liveData);
    const wait = extractStandby(match);
    if (wait >= Number(state.settings.longWaitThreshold||60)) notifyOnce(`wait-${next.id}-${Math.floor(wait/15)}`, 'Fila longa na próxima atração', `${next.title}: ${wait} min. Abra “Ao vivo” para alternativas.`);
  }
}

function notifyOnce(key, title, body) {
  const last = state.lastAlertKeys[key] || 0;
  if (Date.now()-last < 45*60*1000) return;
  state.lastAlertKeys[key] = Date.now(); saveState();
  toast(`${title}: ${body}`);
  if (Notification.permission === 'granted' && document.visibilityState === 'visible') {
    try { new Notification(title, { body, icon:'./icons/icon-192.png' }); } catch {}
  }
}

function startActivity(id) {
  const day = getSelectedDay();
  const a = day?.activities.find(a=>a.id===id); if (!a || isDone(id)) return;
  state.history = state.history.filter(h=>!(h.activityId===id && h.status==='started'));
  state.history.push({ activityId:id, date:day.date, title:a.title, status:'started', actualStart:new Date().toISOString() });
  saveState(); renderAll(); toast(`${a.title} iniciada.`);
}

function completionMode(activity) {
  const type = String(activity?.type || 'other').toLowerCase();
  if (['travel','transport','arrival','break'].includes(type)) return 'instant';
  if (['meal','restaurant','food'].includes(type)) return 'meal';
  if (type === 'attraction') return 'attraction';
  return 'experience';
}

function completeWithoutInputs(id) {
  const day = getSelectedDay();
  const a = day?.activities.find(x=>x.id===id);
  if (!a) return;
  const started = state.history.find(h=>h.activityId===id && h.status==='started');
  state.history = state.history.filter(h=>h.activityId!==id || h.status==='skipped');
  state.history.push({
    activityId:id,
    date:day.date,
    title:a.title,
    type:a.type,
    duration:Number(a.duration||0),
    status:'done',
    actualStart:started?.actualStart || new Date().toISOString(),
    actualEnd:new Date().toISOString()
  });
  saveState();
  renderAll();
  toast(`${a.title} concluída.`);
}

function openComplete(id) {
  const day = getSelectedDay();
  const a = day?.activities.find(x=>x.id===id);
  if (!a) return;

  const mode = completionMode(a);
  if (mode === 'instant') {
    completeWithoutInputs(id);
    return;
  }

  $('#completeActivityId').value = id;
  $('#completeTitle').textContent = a.title;
  $('#attractionCompletionFields').hidden = mode !== 'attraction';
  $('#mealCompletionFields').hidden = mode !== 'meal';
  $('#ratingFieldset').hidden = false;
  $('#commentField').hidden = mode === 'meal';

  const hints = {
    attraction:'Registre só o que ajuda no recap: fila real, nota e um comentário opcional.',
    meal:'Escolha onde vocês realmente comeram agora. Informe o restaurante, o prato/refeição e dê uma nota — nada precisa estar definido no roteiro.',
    experience:'Dê uma nota e, se quiser, um comentário rápido.'
  };
  $('#completeHint').textContent = hints[mode] || '';

  const live = state.liveCache[day.park];
  const wait = mode === 'attraction' ? extractStandby(findLiveMatch(a, live?.liveData || [])) : null;
  $('#actualWaitInput').value = mode === 'attraction' ? (wait ?? a.plannedWait ?? '') : '';
  $('#restaurantNameInput').value = '';
  $('#mealItemInput').value = '';
  $('#commentInput').value = '';
  completionRating = 0;
  const ratingSlider = $('#ratingSlider');
  if (ratingSlider) ratingSlider.value = '0';
  renderRating();
  $('#completeDialog').showModal();
}

function saveCompletion(id) {
  const day = getSelectedDay();
  const a = day?.activities.find(x=>x.id===id);
  if (!a) return;

  const mode = completionMode(a);
  if (mode === 'meal') {
    const restaurantName = $('#restaurantNameInput').value.trim();
    if (!restaurantName) {
      toast('Informe o restaurante/local para entrar no ranking gastronômico.');
      $('#restaurantNameInput').focus();
      return false;
    }
    if (!completionRating) {
      toast('Dê uma nota para registrar a refeição no ranking.');
      $('#ratingFieldset').focus?.();
      return false;
    }
  }

  const started = state.history.find(h=>h.activityId===id && h.status==='started');
  const weather = relevantWeather(state.weatherCache[day.park]);
  state.history = state.history.filter(h=>h.activityId!==id || h.status==='skipped');

  const record = {
    activityId:id,
    date:day.date,
    title:a.title,
    type:a.type,
    duration:Number(a.duration||0),
    status:'done',
    actualStart:started?.actualStart || new Date().toISOString(),
    actualEnd:new Date().toISOString(),
    rating:completionRating,
    weatherRiskAtCompletion: {
      level:weather.risk?.level || 'low',
      score:Number(weather.risk?.score || 0),
      label:weather.risk?.label || 'baixo'
    }
  };

  if (mode === 'attraction') {
    record.actualWait = Number($('#actualWaitInput').value || 0);
    record.comment = $('#commentInput').value.trim();
  } else if (mode === 'meal') {
    record.restaurantName = $('#restaurantNameInput').value.trim();
    record.mealItem = $('#mealItemInput').value.trim();
  } else {
    record.comment = $('#commentInput').value.trim();
  }

  state.history.push(record);
  saveState();
  renderAll();
  toast(mode === 'meal' ? 'Refeição registrada no ranking gastronômico.' : 'Atividade registrada no histórico.');
  return true;
}

function skipActivity(id) {
  const day = getSelectedDay();
  const a = day?.activities.find(a=>a.id===id);
  if (!a) return;
  state.history = state.history.filter(h=>h.activityId!==id);
  state.history.push({ activityId:id, date:day.date, title:a.title, type:a.type, status:'skipped', actualEnd:new Date().toISOString() });

  const recoverable = a.type === 'attraction' && day.date === getOrlandoParts().date;
  if (recoverable) {
    delete state.replanDecisions[day.date];
    delete state.lastReplanAnalyses[day.date];
    currentReplanProposal = null;
    currentReplanJson = null;
    forceReplanAnalysis = true;
  }

  saveState();
  renderAll();

  if (!recoverable) {
    toast(`${a.title} foi pulada.`);
    return;
  }

  switchView('live');
  toast(`${a.title} foi pulada. Procurando o melhor encaixe no restante do dia…`);
  refreshExternal(false)
    .then(()=>{ forceReplanAnalysis = true; renderLive(); toast('Replanejamento atualizado com a atração pulada.'); })
    .catch(()=>{ forceReplanAnalysis = true; renderLive(); });
}

function renderRating() {
  const rating = normalizeRating(completionRating);
  const fill = $('#ratingFill');
  const value = $('#ratingValue');
  const slider = $('#ratingSlider');
  if (fill) fill.style.width = `${rating / 5 * 100}%`;
  if (value) value.textContent = rating ? `${rating.toFixed(1).replace('.', ',')} / 5` : 'Sem nota';
  if (slider && Number(slider.value) !== rating) slider.value = String(rating);
}

function toast(message) {
  const el = $('#toast'); el.textContent = message; el.classList.add('show');
  clearTimeout(el._t); el._t = setTimeout(()=>el.classList.remove('show'), 3200);
}

function escapeHtml(v='') { return String(v).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }

function switchView(target) {
  $$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===target));
  $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.target===target));
  window.scrollTo({top:0,behavior:'smooth'});
  if (target==='report') renderReport();
}

function renderNetwork() {
  $('#netPill').textContent = navigator.onLine ? 'online' : 'offline';
  $('#netPill').classList.toggle('offline',!navigator.onLine);
}

function downloadBlob(name, blob) {
  const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href=url; a.download=name; a.click();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}

function exportBackup() {
  downloadBlob(`orlando-flow-backup-${getOrlandoParts().date}.json`, new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));
}

function validateImportedTrip(data) {
  if (!data || !Array.isArray(data.days)) throw new Error('O JSON precisa conter um array "days".');
  for (const day of data.days) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day.date||'') || !Array.isArray(day.activities)) throw new Error('Cada dia precisa de date (YYYY-MM-DD) e activities[].');
    for (const a of day.activities) if (!a.id || !/^\d{2}:\d{2}$/.test(a.time||'') || !a.title) throw new Error('Cada atividade precisa de id, time (HH:MM) e title.');
  }
}

function exportGroupSectionHtml(title, records, parkKey = null, brand = null) {
  const m = historyMetrics(records);
  const ranked = records.filter(r=>isAttractionRecord(r) && normalizeRating(r.rating))
    .sort((a,b)=>normalizeRating(b.rating)-normalizeRating(a.rating) || Number(a.actualWait||0)-Number(b.actualWait||0))
    .slice(0,5);
  const restaurantRows = restaurantRanking(records).slice(0,5);
  const dates = [...new Set(records.map(r=>r.date))];
  const movement = movementMetricsForDates(dates);
  const attrs = ranked.map((r,i)=>`<tr><td>${i+1}</td><td>${escapeHtml(activityForRecord(r)?.title||r.title)}</td><td>${escapeHtml(formatRating(r.rating,true))}</td><td>${Number(r.actualWait||0)} min</td></tr>`).join('');
  const meals = restaurantRows.map((x,i)=>`<tr><td>${i+1}</td><td>${escapeHtml(x.name)}</td><td>${x.avg?x.avg.toFixed(1).replace('.', ',')+' ★':'--'}</td><td>${escapeHtml([...new Set(x.dishes)].slice(0,2).join(' / '))}</td></tr>`).join('');
  const icon = parkKey
    ? parkIconSvg(parkKey, 'export-park-icon')
    : brand === 'disney'
      ? `<img class="export-franchise-logo" src="${DISNEY_REPORT_LOGO}" alt="">`
      : brand === 'universal'
        ? `<img class="export-franchise-logo" src="${UNIVERSAL_REPORT_LOGO}" alt="">`
        : '';
  return `<section class="group-section"><div class="group-title">${icon}<div><small>${parkKey?'PARQUE':'FRANQUIA'}</small><h2>${escapeHtml(title)}</h2></div></div><div class="grid"><div class="card"><b>${m.attractionCount}</b><br>Atrações</div><div class="card"><b>${m.attractionCount?Math.round(m.avgWait)+' min':'--'}</b><br>Fila média</div><div class="card"><b>${m.avgRating?m.avgRating.toFixed(1).replace('.', ','):'--'}</b><br>Nota média</div><div class="card"><b>${movement.steps?movement.steps.toLocaleString('pt-BR'):'--'}</b><br>Passos</div></div><h3>Top atrações</h3><table><thead><tr><th>#</th><th>Atração</th><th>Nota</th><th>Fila</th></tr></thead><tbody>${attrs||'<tr><td colspan="4">Sem atrações avaliadas.</td></tr>'}</tbody></table><h3>Restaurantes</h3><table><thead><tr><th>#</th><th>Restaurante</th><th>Nota</th><th>Pratos</th></tr></thead><tbody>${meals||'<tr><td colspan="4">Sem refeições avaliadas.</td></tr>'}</tbody></table></section>`;
}

function buildReportHtml() {
  const records = reportRecords();
  const m = historyMetrics(records);
  const scope = $('#reportScope').value;
  const movement = movementMetricsForScope(scope);
  const insights = reportInsights(records, scope);
  const title = scope==='trip' ? state.tripName : getSelectedDay()?.label;
  const parkKey = scope === 'day' ? (getSelectedDay()?.park || state.selectedPark) : state.selectedPark;
  const theme = getParkThemeConfig(parkKey).report;

  const attractionRows = records.filter(r=>isAttractionRecord(r) && normalizeRating(r.rating))
    .sort((a,b)=>normalizeRating(b.rating)-normalizeRating(a.rating) || Number(a.actualWait||0)-Number(b.actualWait||0))
    .map((r,i)=>{
      const a=activityForRecord(r);
      return `<tr><td>${i+1}</td><td>${escapeHtml(a?.title||r.title)}</td><td>${escapeHtml(formatRating(r.rating,true))}</td><td>${Number(r.actualWait||0)} min</td><td>${escapeHtml(r.comment||'')}</td></tr>`;
    }).join('');

  const restaurantRows = restaurantRanking(records).map((x,i)=>
    `<tr><td>${i+1}</td><td>${escapeHtml(x.name)}</td><td>${x.avg?x.avg.toFixed(1).replace('.', ',')+' ★':'--'}</td><td>${x.visits}</td><td>${escapeHtml([...new Set(x.dishes)].join(' / '))}</td></tr>`
  ).join('');

  const insightItems = [
    ['Tempo em atrações', insights.attractionMinutes ? `${insights.attractionMinutes} min` : '--'],
    ['Atração mais repetida', insights.repeated ? `${insights.repeated.name}${insights.repeated.count>1?` ×${insights.repeated.count}`:''}` : '--'],
    ['Fila média', m.attractionCount ? `${Math.round(m.avgWait)} min` : '--'],
    ['Replanejamentos aplicados', String(insights.appliedReplans)],
    ['Impactos de clima', String(insights.weatherReplans + insights.weatherAffected)],
    ['Fila poupada vs. planejado', `${insights.savedWait} min`]
  ].map(([label,value])=>`<div class="card"><b>${escapeHtml(String(value))}</b><br>${escapeHtml(label)}</div>`).join('');

  const franchiseSections = ['disney','universal'].map(brand=>{
    const subset=records.filter(r=>getParkThemeConfig(parkKeyForRecord(r)).brand===brand);
    return subset.length?exportGroupSectionHtml(FRANCHISE_LABELS[brand],subset,null,brand):'';
  }).join('');
  const parkOrder=['magic-kingdom','epcot','hollywood-studios','animal-kingdom','universal-studios-florida','islands-of-adventure','epic-universe'];
  const parkSections=parkOrder.map(key=>{
    const subset=records.filter(r=>parkKeyForRecord(r)===key);
    return subset.length?exportGroupSectionHtml(PARKS[key].name,subset,key):'';
  }).join('');
  const calories = movement.calories == null ? '--' : `~${movement.calories.toLocaleString('pt-BR')} kcal`;

  return `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)} · Orlando Recap</title><style>
  :root{--bg:${theme.bg};--surface:${theme.surface};--ink:${theme.ink};--accent:${theme.accent}}
  body{font-family:system-ui,-apple-system,sans-serif;margin:0;background:var(--bg);color:var(--ink)}
  .wrap{max-width:960px;margin:auto;padding:24px}.hero{background:linear-gradient(135deg,${theme.gradient[0]},${theme.gradient[1]} 58%,${theme.gradient[2]});color:#fff;padding:28px;border-radius:24px}
  .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:16px 0}.card{background:var(--surface);padding:16px;border-radius:16px;border:1px solid color-mix(in srgb,var(--accent) 18%,transparent)}
  .big{font-size:34px;font-weight:900}.tier{margin-top:32px;padding-top:8px}.tier>h2{font-size:25px}.group-section{margin-top:18px;background:color-mix(in srgb,var(--surface) 92%,var(--accent));padding:18px;border-radius:20px;border:1px solid color-mix(in srgb,var(--accent) 18%,transparent)}
  .group-title{display:flex;align-items:center;gap:12px}.group-title h2{margin:0}.group-title small{opacity:.65;font-weight:800;letter-spacing:.12em}.export-franchise-logo{width:52px;height:42px;object-fit:contain;display:block;background:#fff;border-radius:12px;padding:5px;box-sizing:border-box}.export-park-icon{width:44px;height:44px;fill:none;stroke:var(--accent);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.export-park-icon .park-icon-fill{fill:var(--accent);stroke:none}.export-park-icon .park-icon-soft{fill:var(--accent);stroke:none;opacity:.18}.export-park-icon .park-icon-thin{stroke-width:1.05}.export-park-icon .park-icon-bold{stroke-width:2.3}
  h2,h3{color:var(--accent);margin-top:24px}table{width:100%;border-collapse:collapse;background:var(--surface);border-radius:16px;overflow:hidden}td,th{padding:10px;border-bottom:1px solid color-mix(in srgb,var(--accent) 12%,transparent);text-align:left;font-size:14px}
  @media(max-width:600px){.wrap{padding:12px}table{font-size:12px}.hero{padding:20px}.group-section{padding:12px}}
  </style><div class="wrap">
  <div class="hero"><div>ORLANDO RECAP</div><div class="big">${escapeHtml(title||'Nossa viagem')}</div><p>${m.attractionCount} atrações · ${formatDistance(movement.distanceMeters)} · ${movement.steps.toLocaleString('pt-BR')} passos</p></div>
  <div class="grid"><div class="card"><b>${formatDistance(movement.distanceMeters)}</b><br>Distância GPS</div><div class="card"><b>${movement.steps.toLocaleString('pt-BR')}</b><br>Passos estimados</div><div class="card"><b>${calories}</b><br>Calorias estimadas</div><div class="card"><b>${m.attractionCount?Math.round(m.avgWait)+' min':'--'}</b><br>Fila média</div></div>
  <section class="tier"><h2>Melhores de todos</h2><h3>Insights</h3><div class="grid">${insightItems}</div><h3>Ranking das atrações</h3><table><thead><tr><th>#</th><th>Atração</th><th>Nota</th><th>Fila</th><th>Comentário</th></tr></thead><tbody>${attractionRows||'<tr><td colspan="5">Sem avaliações de atrações ainda.</td></tr>'}</tbody></table><h3>Ranking de restaurantes & pratos</h3><table><thead><tr><th>#</th><th>Restaurante</th><th>Nota</th><th>Visitas</th><th>Pratos</th></tr></thead><tbody>${restaurantRows||'<tr><td colspan="5">Sem refeições avaliadas ainda.</td></tr>'}</tbody></table></section>
  <section class="tier"><h2>Por franquia</h2>${franchiseSections||'<p>Sem dados suficientes por franquia.</p>'}</section>
  <section class="tier"><h2>Por parque</h2>${parkSections||'<p>Sem dados suficientes por parque.</p>'}</section>
  <p style="opacity:.72;margin-top:28px;font-size:12px">Distância por GPS; passos e calorias são estimativas.</p>
  </div></html>`;
}

function exportReport() {
  const scope=$('#reportScope').value; downloadBlob(`orlando-recap-${scope}-${getOrlandoParts().date}.html`,new Blob([buildReportHtml()],{type:'text/html'}));
}

async function shareCard() {
  const records=reportRecords();
  const m=historyMetrics(records);
  const scope=$('#reportScope').value;
  const movement=movementMetricsForScope(scope);
  const favorite=favoriteExperience(records);
  const favoriteName=favorite ? (favorite.a?.title || favorite.r.title) : 'Ainda escolhendo';
  const parkKey=scope==='day'?(getSelectedDay()?.park||state.selectedPark):state.selectedPark;
  const cardTheme=getParkThemeConfig(parkKey).report;
  const canvas=document.createElement('canvas'); canvas.width=1080; canvas.height=1350; const ctx=canvas.getContext('2d');
  const cardGradient=ctx.createLinearGradient(0,0,1080,1350); cardGradient.addColorStop(0,cardTheme.gradient[0]); cardGradient.addColorStop(.58,cardTheme.gradient[1]); cardGradient.addColorStop(1,cardTheme.gradient[2]); ctx.fillStyle=cardGradient; ctx.fillRect(0,0,1080,1350); ctx.fillStyle='#ffffff';
  ctx.font='700 36px system-ui'; ctx.fillText('ORLANDO RECAP',70,100); ctx.font='900 72px system-ui'; wrapText(ctx,scope==='trip'?(state.tripName||'Nossa viagem'):(getSelectedDay()?.label||'Nosso dia'),70,205,930,82);
  ctx.fillStyle=cardTheme.muted; ctx.font='500 30px system-ui'; ctx.fillText(`${m.attractionCount} atrações registradas`,70,360);
  const stats=[
    ['DISTÂNCIA',formatDistance(movement.distanceMeters)],
    ['PASSOS',movement.steps?movement.steps.toLocaleString('pt-BR'):'--'],
    ['CALORIAS',movement.calories==null?'--':`~${movement.calories} kcal`],
    ['FAVORITA',favoriteName]
  ];
  let y=470; for(const [l,v] of stats){ctx.fillStyle=cardTheme.muted;ctx.font='700 24px system-ui';ctx.fillText(l,70,y);ctx.fillStyle='#fff';ctx.font=String(v).length>24?'800 36px system-ui':'900 52px system-ui';wrapText(ctx,String(v),70,y+55,900,50);y+=190;}
  ctx.fillStyle=cardTheme.muted;ctx.font='500 25px system-ui';ctx.fillText('feito com Orlando Flow ✦',70,1270);
  const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));
  const file=new File([blob],`orlando-recap-${getOrlandoParts().date}.png`,{type:'image/png'});
  if (navigator.share && navigator.canShare?.({files:[file]})) await navigator.share({title:'Orlando Recap',text:'Nosso resumo de Orlando ✨',files:[file]});
  else { downloadBlob(file.name,blob); toast('Card gerado. O navegador baixou o PNG para compartilhar.'); }
}

function wrapText(ctx,text,x,y,maxWidth,lineHeight){const words=String(text).split(' ');let line='';for(let n=0;n<words.length;n++){const test=line+words[n]+' ';if(ctx.measureText(test).width>maxWidth&&n>0){ctx.fillText(line,x,y);line=words[n]+' ';y+=lineHeight;}else line=test;}ctx.fillText(line,x,y);return y;}

function bindEvents() {
  $$('.nav-item').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.target)));
  $('#themeToggleBtn').addEventListener('click',()=>{
    state.settings.darkMode = !Boolean(state.settings.darkMode);
    saveState();
    applyTheme();
    toast(state.settings.darkMode ? 'Modo escuro ativado.' : 'Modo claro ativado.');
  });
  $('#refreshBtn').addEventListener('click',()=>refreshExternal());
  $('#liveRefreshBtn').addEventListener('click',async()=>{ await fetchLive(state.selectedPark); await fetchWeather(state.selectedPark); renderAll(); evaluateAlerts(); });
  $('#optimizeBtn').addEventListener('click',async()=>{ forceReplanAnalysis=true; switchView('live'); await refreshExternal(false); renderLive(); });
  $('#daySelect').addEventListener('change',e=>{ state.selectedDate=e.target.value; const d=getSelectedDay(); if(d?.park && PARKS[d.park]?.entityId) state.selectedPark=d.park; saveState(); renderAll(); });
  $('#parkSelect').addEventListener('change',e=>{ state.selectedPark=e.target.value; saveState(); renderAll(); fetchLive(state.selectedPark).then(()=>renderLive()); fetchWeather(state.selectedPark).then(()=>renderWeather()); });
  $('#waitFilter').addEventListener('change',renderLive);
  $('#liveAttractionSearch').addEventListener('input',renderLive);
  $('#analyzeReplanBtn').addEventListener('click',()=>{ forceReplanAnalysis=true; renderLive(); });
  $('#downloadReplanJsonBtn').addEventListener('click',downloadCurrentReplanJson);
  $('#keepOriginalBtn').addEventListener('click',keepOriginalRoute);
  $('#applyReplanBtn').addEventListener('click',applyReplanProposal);
  document.addEventListener('click',e=>{ const start=e.target.closest('[data-start]'), complete=e.target.closest('[data-complete]'), skip=e.target.closest('[data-skip]'); if(start)startActivity(start.dataset.start); if(complete)openComplete(complete.dataset.complete); if(skip)skipActivity(skip.dataset.skip); });
  $('#ratingSlider').addEventListener('input',e=>{ completionRating=normalizeRating(e.target.value); renderRating(); });
  $('#saveCompletionBtn').addEventListener('click',e=>{
    e.preventDefault();
    const id=$('#completeActivityId').value;
    if (saveCompletion(id)) $('#completeDialog').close();
  });
  $('#clearHistoryBtn').addEventListener('click',()=>{ if(confirm('Apagar todo o histórico e avaliações?')){state.history=[];saveState();renderAll();} });
  $('#reportScope').addEventListener('change',renderReport);
  $('#shareCardBtn').addEventListener('click',shareCard);
  $('#exportReportBtn').addEventListener('click',exportReport);
  $('#exportDataBtn').addEventListener('click',exportBackup);
  $('#loadDemoBtn').addEventListener('click',async()=>{ if(confirm('Substituir o roteiro atual pelo exemplo?')){await loadDemo();renderAll();} });
  $('#importInput').addEventListener('change',async e=>{ const file=e.target.files?.[0]; if(!file)return; try{const data=JSON.parse(await file.text());validateImportedTrip(data);state.tripName=data.tripName||state.tripName;state.timezone=data.timezone||ORLANDO_TZ;state.settings={...state.settings,...(data.settings||{})};state.days=data.days;state.history=data.history||[];state.stepsByDate=data.stepsByDate||{};state.movementByDate=data.movementByDate||{};state.originalPlans=data.originalPlans||snapshotOriginalPlans(state.days);state.replanDecisions=data.replanDecisions||{};state.replanHistory=data.replanHistory||[];state.lastReplanAnalyses=data.lastReplanAnalyses||{};state.selectedDate=chooseRelevantDate();const d=getSelectedDay();if(PARKS[d?.park]?.entityId)state.selectedPark=d.park;ensureOriginalPlans();saveState();renderAll();toast('Roteiro importado com sucesso.');}catch(err){alert(`Não foi possível importar: ${err.message}`);} finally{e.target.value='';} });
  $('#tripNameInput').addEventListener('change',e=>{state.tripName=e.target.value.trim()||'Orlando Flow';saveState();renderHeader();});
  $('#delayThreshold').addEventListener('input',e=>{$('#delayThresholdValue').textContent=`${e.target.value} min`;});
  $('#delayThreshold').addEventListener('change',e=>{state.settings.delayThreshold=Number(e.target.value);saveState();renderStatus();});
  $('#longWaitThreshold').addEventListener('input',e=>{$('#longWaitThresholdValue').textContent=`${e.target.value} min`;});
  $('#longWaitThreshold').addEventListener('change',e=>{state.settings.longWaitThreshold=Number(e.target.value);saveState();renderAll();});
  $('#strideCmInput').addEventListener('change',e=>{state.settings.strideCm=Math.max(40,Math.min(120,Number(e.target.value||75)));saveState();renderAll();});
  $('#weightKgInput').addEventListener('change',e=>{const v=Number(e.target.value||0);state.settings.weightKg=v>0?Math.max(30,Math.min(250,v)):'';saveState();renderAll();});
  $('#gpsToggleBtn').addEventListener('click',toggleGpsTracking);
  $('#gpsSettingsBtn').addEventListener('click',toggleGpsTracking);
  $('#resetMovementBtn').addEventListener('click',resetMovementForToday);
  $('#notificationBtn').addEventListener('click',async()=>{ if(!('Notification'in window)){toast('Este navegador não oferece notificações web.');return;}const p=await Notification.requestPermission();renderSettings();toast(p==='granted'?'Notificações ativadas.':'Permissão de notificação não concedida.'); });
  $('#installBtn').addEventListener('click',async()=>{ if(!deferredInstallPrompt)return; deferredInstallPrompt.prompt(); await deferredInstallPrompt.userChoice; deferredInstallPrompt=null; $('#installBtn').hidden=true; });
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installBtn').hidden=false;});
  window.addEventListener('online',()=>{renderNetwork();refreshExternal(false);});
  window.addEventListener('offline',renderNetwork);
  window.addEventListener('pagehide',()=>saveState());
  document.addEventListener('visibilitychange',()=>{ if(document.visibilityState==='visible'){renderAll();evaluateAlerts();} });
}

async function init() {
  await loadState();
  applyParkTheme();
  applyTheme();
  bindEvents();
  renderAll();
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').catch(()=>{});
  refreshExternal(false);
  setInterval(()=>{ renderHeader(); renderStatus(); renderNext(); }, 60_000);
  alertTimer = setInterval(()=>{ if(document.visibilityState==='visible' && navigator.onLine) refreshExternal(false); else evaluateAlerts(); }, 5*60_000);
}

init();
